// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(address caller, uint256 amount, address receiver) public {
        amount = bound(amount, 1, 100 ether);
        vm.assume(receiver != address(0));
        vm.assume(caller != address(this));

        vm.deal(address(c), amount);

        bool succeeded;
        vm.prank(caller);
        try c.sendTo(receiver, amount) {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        assertTrue(!succeeded || caller == address(this), "Non-owner caller succeeded");
    }
}
